// Cryptic and brittle
const sync = async (d: any) => {
  const r = await fetch('/api/inv', { method: 'POST', body: JSON.stringify(d) });
  return r.json();
};

// Explicit and descriptive
export async function synchronizeInventoryRecords(
  pendingStockUpdate: StockUpdateBatch
): Promise<InventorySyncReceipt> {
  const response = await fetch('/api/inventory/batch-sync', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(pendingStockUpdate),
  });
  return response.json();
}
